from pathlib import Path
import html,json,re
E=html.escape
pages=[]
groups=['자생 브랜드 스토리','자생치료법','자생인의 마인드','슬기로운 자생생활','자생인 건강지킴이']
def p(s):return '<p>'+s+'</p>'
def ul(*xs):return '<ul>'+''.join('<li>'+s+'</li>' for s in xs)+'</ul>'
def sec(t,s):return '<section><h2>'+t+'</h2>'+s+'</section>'
def sub(t,s):return '<h3>'+t+'</h3>'+s
def fig(n,alt,cap=''):return f'<figure><img src="assets/{n}.webp" alt="{E(alt)}" loading="lazy"><figcaption>{cap or alt}</figcaption></figure>'
def note(t,s):return f'<aside class="notice"><strong>{t}</strong>{p(s)}</aside>'
def more(t,s):return f'<details class="supplement"><summary>{t}</summary><div>{s}</div></details>'
def timeline(items):return '<ol class="timeline">'+''.join(f'<li><strong>{a}</strong><div>{b}</div></li>' for a,b in items)+'</ol>'
def cases(items):return '<div class="situations">'+''.join(f'<section class="situation"><h3>{a}</h3>{p(b)}'+(f'<div class="example">{c}</div>' if c else '')+'</section>' for a,b,c in items)+'</div>'
def add(g,slug,title,lead,body):pages.append(dict(g=g,slug=slug,title=title,lead=lead,body=body))
add(1,'index','자생 소개','환자의 아픔을 가족의 아픔처럼 이해하는 긍휼지심. 자생의 철학은 이 마음에서 시작합니다.',
 sec('긍휼지심과 자생력',sub('긍휼지심 矜恤之心',p('환자의 아픔을 내 가족의 아픔처럼 느끼고, 진심으로 열과 성을 다해 진료에 임하려는 마음입니다.'))+sub('자생력 自生力',p('인체 스스로 질병을 치유하는 힘을 뜻합니다. 자생의 치료 철학은 일시적인 통증 감소를 넘어 이 힘을 키워 질병의 근본적인 치료와 재발 방지를 지향합니다.')))+
 sec('병원의 정체성과 치료 철학',p('자생한방병원은 독립운동 정신과 긍휼지심을 근간으로 설립된 한방 비수술 척추·관절 치료 병원입니다. 설립자 신준식 박사의 선친 청파 신광렬 선생은 항일운동을 펼치고, 한의학을 되살리며 아픈 이들의 몸과 마음을 가족처럼 보살피는 인술을 강조했습니다.')+p('이 철학은 진료뿐 아니라 의료·한의학 연구개발과 사회공헌 활동으로 이어집니다. 한의학의 과학화·표준화·세계화를 통해 치료를 발전시키는 것도 같은 맥락입니다.'))+
 sec('가이드에서 찾아보기','<div class="quicklinks"><a href="values.html">미션·비전과 핵심가치 →</a><a href="integrated.html">자생 통합진료시스템 →</a><a href="phone.html">전화예절 →</a><a href="posture.html">생활 속 바른 자세 →</a></div>'))
add(1,'roots','민족병원 자생','독립운동과 의료 활동을 함께 이어온 가문의 역사는 자생의 긍휼지심과 비수술 치료 철학의 뿌리입니다.',
 sec('신홍균 선생',p('신홍균 선생(1881.8.20 ~ 1948.10.20)은 한의사이자 독립운동가이며, 신준식 박사의 숙조부입니다. 만주 일대에서 항일활동을 했으며 한국독립군 대진단 단장이자 군의관으로 활동했습니다.')+timeline([('1920년','독립운동가 김중건과 함께 독립군 대진단 창설'),('1933년','지청천 장군이 이끄는 독립군에 합류. 사도하자·동경성·대전자령 전투 등에 참전'),('~1941년','한중반일회 및 동북항일연군과 연계해 항일 투쟁 지속'),('2020년','건국훈장 애족장 추서')])+more('대전자령 전투와 목이버섯 이야기',p('일본군을 기다리던 독립군은 예상치 못한 폭우로 산속에서 3일 동안 추위와 배고픔을 견뎌야 했습니다. 군의관 신홍균 선생은 한의학 지식으로 주변의 목이버섯을 식량으로 활용했습니다. 병사들이 기운을 되찾고 전투를 이어갈 수 있도록 도운 이야기입니다.')))+
 sec('청파 신광렬 선생',p('신광렬 선생(1903. 2. 13 ~ 1980. 11. 11)은 의사·한의사·독립운동가이며 신준식 박사의 선친입니다. 독립운동의 기록과 의료 철학을 후대에 남겼습니다.')+timeline([('1924년','만주 독립군 산하 제일 정몽 학교 교사 재직'),('1930년','3·1운동 11주년 기념 만세운동 주도, 서대문형무소 수감'),('1932년','만주에서 광생의원을 개원해 독립운동가 지원·치료'),('1946년','해방 후 신익희 선생과 구국활동'),('1959년','청파험방요결 집필'),('2022년','대통령표창 서훈')]))+
 sec('자생의 뿌리가 된 두 기록',sub('월남유서',p('독립운동 일대기와 가문의 발자취, 의료인으로서의 철학을 담았습니다. 긍휼지심을 바탕으로 한의학을 과학적으로 발전시켜 가업을 이어가기를 바란다는 뜻을 전합니다.'))+sub('청파험방요결',p('7대에 걸친 한의서이자 신광렬 선생이 평생 손수 작성한 임상기록입니다. 한방 치료 연구와 임상 결과를 기록했으며, 자생 비수술 치료법의 근간이 되는 내용을 담고 있습니다.'))))
add(1,'values','미션·비전과 핵심가치','미션은 자생이 기여할 방향을, 비전은 지향하는 병원의 모습을, DOING은 함께 일하는 가치 기준을 나타냅니다.',
 sec('미션과 비전','<div class="concept"><h3>미션</h3>'+p('한의학과 의학의 장점을 살린 통합의학으로,<br>의술을 넘어 인술로써 고통 받는 환자의 건강한 삶을 위해 기여하겠습니다.')+'</div><div class="concept"><h3>비전</h3>'+p('표준화, 과학화, 세계화된 치료법으로<br>전세계 비수술 척추치료를 선도하는 병원')+'</div>')+
 sec('핵심가치 DOING',cases([('D · Dedication — 고객중심','표준화, 과학화, 세계화된 치료법으로 전세계 비수술 척추치료를 선도하는 병원을 지향합니다.',''),('O · Ownership — 주인의식','자생인은 모두가 주인입니다.',''),('I · Innovation — 변화선도','혁신을 두려워하지 않고 변화를 선도합니다.',''),('N · Now — 실행중심','기획은 치밀하게, 실행은 즉시 합니다.',''),('G · Growth — 동반성장','개개인의 역량을 발전시켜 모두 함께 성장합니다.','')]))+
 sec('긍휼지심 선서',p('자생은 선대로부터의 독립운동 정신을 이어받아 긍휼지심의 의료철학을 실천하는 민족병원입니다.')+'<blockquote>'+p('나는 독립운동 정신을 이어받은 자긍심으로 변화와 혁신을 두려워하지 않으며, 자생인으로서 맡은 바 직무를 충실히 수행하겠습니다.')+p('나는 아픈 환자의 몸을 내 몸과 같이 여기는 긍휼지심의 정신을 바탕으로 의술을 넘어 인술을 실천하겠습니다.')+p('나는 인체의 자생력을 바탕으로 한 자생치료법으로 전 세계 비수술 척추치료를 선도하며 고통 받는 환자의 건강한 삶을 위해 기여하겠습니다.')+'</blockquote>')+
 sec('자생 엠블렘',p('자생의 정통성을 나타내는 상징입니다. 중앙의 물결 문양은 태양·땅·바다를 형상화합니다. 자생력을 상징하는 물이 자연스럽게 교류하는 삼각뿔 형상에는 기(氣)를 다스려 환자를 치유하는 한방의 원리가 담겨 있습니다.')+fig('emblem','태양·땅·바다와 물의 교류를 표현한 자생 엠블렘')))
add(1,'foundation','자생의료재단','의료사업, 한의학 연구개발, 사회공헌을 통해 이웃이 스스로 일어설 힘을 키우도록 돕습니다.',
 sec('설립 목적',p('재단법인 자생의료재단은 2000년 1월 21일 설립된 비영리 재단법인입니다. 어려운 이웃들이 스스로 힘을 키워 자생할 수 있도록 사랑과 정성으로 돕는 것을 목적으로 합니다.')+p('의료혜택을 받지 못하는 소외계층 환자에게 의료서비스를 제공하고 한의학 연구개발을 지원하고자, 자생한방병원은 653억원을 사회에 출연했습니다. 의료사업의 수익은 사회공헌 활동으로 환원됩니다.'))+
 sec('자생척추관절연구소',p('자생척추관절연구소(JSR)는 자생의료재단이 설립한 독자적인 연구기관입니다. 비수술 척추디스크 치료의 안전성과 유효성 근거를 마련하기 위한 기초·임상 연구와 기술 개발을 수행합니다.')+ul('한의약의 특성을 반영한 의약품·의료기기 임상시험','한의통합치료의 경제성 평가','한의학의 과학화·표준화·세계화를 위한 연구')+p('통합의학 전문 영문 국제학술지 Perspectives on Integrative Medicine(PIM)은 한의학과 통합의학 분야의 치료 기전 및 과학적 근거를 다룹니다.'))+
 sec('사회공헌 활동',cases([('독립유공자 지원 및 보훈활동','생존 애국지사와 귀환국군포로 참전유공자 의료지원',''),('사회취약계층 의료지원','농업인 행복버스와 지역사회 의료봉사',''),('저소득 가정 아동·청소년 지원','자생 Angel box 전달과 자생 희망드림 장학사업',''),('꿈나무 지원 장학사업','자생 꿈나무 올림픽과 한의사 직업체험',''),('이웃과 나누는 사회복지','사랑의 연탄 나누기와 김장김치 나누기','')])) )
add(1,'media','언론 속 자생','비수술 치료에 관한 논의, 국제 교육·학술 교류, 독립운동의 역사와 나눔 활동을 중심으로 자생의 발자취를 살펴봅니다.',
 sec('치료와 학술 교류',timeline([('2001년','신준식 박사가 정형외과·신경외과 전문가들과 허리병과 만성 요통 치료를 주제로 대담했습니다.'),('2015년','미국 침술의학회(AAMA) 컨퍼런스에서 신경근회복술을 소개했습니다.'),('2018년','제1회 자생국제학술대회에서 추나요법 연구성과와 해외 수기치료·의료체계 등을 논의했습니다.'),('2019년','미국 국방부 건강국(DHA) 주최 원격 보수교육에서 의료전문가 600여 명을 대상으로 한방 비수술 치료법을 강의했습니다.'),('2021년','미국 평생의학교육인증원(ACCME) 정식 인증 보수교육 제공기관 자격 획득이 소개되었습니다.'),('2022년','목 통증 치료에서 추나요법의 유효성과 경제성에 관한 연구가 소개되었습니다.')]))+
 sec('역사와 나눔',p('신홍균·신광렬 선생의 독립운동을 입증하기 위해 월남유서와 국내외 기록을 조사한 과정이 조명되었습니다.')+p('2019년에는 신준식 박사가 독립유공자유족회에 장학금 1억원을 기탁했습니다. 독립유공자 후손 대학생 10명의 학업과 유가족 3명의 특별생계지원에 사용하기 위한 나눔입니다.')+p('2022년에는 한의과대학 및 한의학전문대학원생에게 장학금과 장학증서를 전달한 활동이 소개되었습니다.')))
add(2,'history','자생치료의 연혁','비수술 척추치료의 개발은 연구, 진료의 표준화, 국제 교육·교류로 이어졌습니다.',
 sec('주요 연혁',timeline([('1985년','자생의학회 발족, 추나요법 연구 시작'),('1989년','척추치료 한약 청파전 개발'),('1990년','역삼동 자생한의원 개원, 특수침법 MSAT 개발'),('1995년','한국추나학 및 한국추나학 임상표준지침서 발간'),('1999년','자생한방병원 확장 개원'),('2001년','신바로한약에서 신바로메틴 발견'),('2003년','신바로메틴 미국 물질특허 획득'),('2005년','한의사·의사 협진시스템 오픈'),('2007년','자생원외탕전실 개설'),('2009년','미국 풀러튼 자생통합의료센터 개원'),('2011년','신바로캡슐 국내 천연물신약 4호 개발, 식약처 승인'),('2012년','경혈주입용 한약 신바로약침 개발'),('2013년','급성 요통에 대한 MSAT 치료 연구가 PAIN에 게재'),('2014년','MSAT 치료 기기 개발'),('2019년','추나요법 국민건강보험 적용'),('2020년','글로벌 의학교육 플랫폼 자생메디컬아카데미 오픈'),('2021년','미국 ACCME 정식교육기관 인증')]))+
 sec('과학화·표준화·세계화',sub('과학화',p('청파험방요결의 처방을 발전시킨 청파전의 효능을 연구하고, 서울대 천연물연구소와 공동연구를 통해 신바로메틴을 발견했습니다. 녹십자와의 8년간 공동연구는 신바로캡슐 개발로 이어졌습니다.'))+sub('표준화',p('한의사·의사 협진시스템, 전문 수련병원 교육, 정기적인 의료진 교육과 정보 공유를 통해 진단·치료의 표준화를 추진했습니다.'))+sub('세계화',p('해외 대학·의료기관과 의료 교육, 연구, 의료진 연수로 교류했습니다. 2006년 국제진료센터를 개설했으며 언어권별 전담 코디네이터가 진료와 서비스 이용을 지원하는 체계를 마련했습니다. 2018년에는 해외환자유치 우수 의료기관 부문 글로벌헬스케어 유공 대통령 표창을 받았습니다.'))))
add(2,'integrated','자생 통합진료시스템','의과의 검사와 한의과의 진단·치료를 연결해 환자 상태에 따른 맞춤치료를 실시합니다.',
 sec('검사에서 치료까지','<ol class="steps"><li><strong>검사와 영상 판독</strong>'+p('X-ray·MRI·CT 등 방사선 검사와 임상병리검사를 활용합니다. 영상의학과 전문의가 영상을 판독해 척추관절질환의 유무와 검진 결과를 제공합니다.')+'</li><li><strong>환자 상태와 질환 진단</strong>'+p('한의사는 검진 결과를 토대로 환자의 상태와 질환을 진단합니다.')+'</li><li><strong>맞춤형 통합치료</strong>'+p('한약·침치료·추나요법과 자세교정·재활치료 등을 연결합니다.')+'</li></ol>')+
 sec('비수술 척추치료의 세 방향',ul('척추관절 주변의 붓고 손상된 조직과 염증·통증에 대한 치료','비뚤어진 척추관절의 교정과 기능 회복을 위한 치료','약해진 뼈와 신경, 척추 주변 조직의 강화·회복을 지향하는 치료')))
add(2,'chuna','추나요법','한의사가 체형과 자세를 살피고 척추·관절·인대·근육을 밀고 당기며, 통증 완화와 기능 회복을 돕는 수기치료입니다.',
 sec('자생 추나요법의 특징',p('요추뿐 아니라 턱·목·등·허리·골반 등 척추 전체의 균형을 살핍니다. 임상 경험을 가진 한의사가 직접 시행하며, 신준식 박사의 추나 경험을 계승·발전시키고 정기 교육을 통해 표준화된 치료를 제공합니다.')+fig('chuna','한의사가 환자의 자세를 잡고 추나요법을 시행하는 모습'))+
 sec('부위별 치료의 이해',cases([('요추 추나요법','틀어진 뼈와 근육을 바로잡아 통증 완화와 척추 기능 회복을 돕습니다.',''),('턱관절 추나요법','턱·목·어깨의 위축되거나 굳은 근육을 풀어 턱관절의 위치와 운동범위 회복을 돕습니다.',''),('경추 추나요법','경추의 고정된 관절을 열어주고 주변 근육을 이완해 통증 감소와 순환을 돕습니다.',''),('관절 추나요법','틀어진 관절을 바로잡고 주변 연부 조직을 풀어 통증 완화와 기능 회복을 돕습니다.','')]))+
 more('추나 교육의 표준화와 건강보험 적용',p('1991년 대한추나의학회(현 척추신경추나의학회) 설립 이후 한국추나학과 표준임상지침서는 12개 한의대·대학원 교재로 채택되어 추나 교육과 치료의 표준화에 기여했습니다. 2019년 4월에는 추나요법에 건강보험이 적용되었습니다.')))
add(2,'herbal','신바로한약','신바로메틴을 바탕으로 개발한 척추관절질환 조제한약으로, 환자 상태에 따라 탕약·환약·약침 등의 형태로 처방합니다.',
 sec('치료의 특징',p('신바로한약은 염증과 통증의 감소, 뼈·연골의 보호, 손상된 신경의 회복을 지향합니다. 척추 주변의 근육과 인대를 포함한 조직을 함께 살피는 자생 비수술 치료의 한 부분입니다.'))+
 sec('연구에서 살펴본 네 가지 작용',p('다음은 동물 및 세포 실험에서 살펴본 작용입니다.')+cases([('염증 및 부종','발에 염증을 유발한 쥐에게 신바로한약을 투여해 염증·부종 변화를 관찰했습니다.',''),('뼈','난소 제거로 골다공증을 유발한 쥐에게 투여한 후 골소주 세포 재생을 관찰했습니다.',''),('신경','마비를 유도한 신경세포에 처리한 후 신경돌기 재생을 관찰했습니다.',''),('연골','연골 손상을 유도한 쥐에게 투여해 연골세포의 변화를 관찰했습니다.','')])) )
add(2,'pharmacopuncture','신바로약침·자생약침','한약재에서 정제·추출한 성분을 경혈과 질환 부위에 직접 주입하는 치료입니다.',
 sec('신바로약침의 이해',p('신바로약침은 신바로한약을 정제·추출해 만든 경혈주입용 한약입니다. 한약과 침의 작용을 함께 활용하며 스테로이드 성분을 사용하지 않는 치료로 소개됩니다.'))+
 sec('자생약침의 특징',ul('한약재 추출물을 통증 부위에 직접 투여','뭉치고 굳은 근육의 이완','기혈의 원활한 순환 촉진','염증 억제를 통한 통증 감소','근육·인대 등 척추 주변 조직 강화'))+
 sec('조제와 품질관리',p('환자별 처방에 맞춰 조제하며, 첨단 시설의 위생관리와 무균 조제 과정을 거칩니다. 약침의 조제와 시험 항목은 <a href="biocenter.html">자생메디바이오센터</a>에서 확인할 수 있습니다.')))
add(2,'nerve','신경근회복술','자생의 특수 시술법으로 신바로약침을 손상 부위에 분사해 신경 회복과 통증 감소를 돕는 치료입니다.',
 sec('치료 과정의 이해',p('MRI 정밀검사로 손상 정도와 부위의 위치를 살핀 뒤, 접근성과 안전성을 고려한 시술을 통해 환부에 약침을 주입합니다.')+fig('nerve','영상진단검사, 정밀한 접근, 신경 회복과 재생을 설명하는 신경근회복술 도해'))+
 sec('관련 연구',p('신바로약침의 핵심성분인 GCSB-5의 신경 회복 관련 연구가 소개되어 있습니다. 손상된 신경의 회복을 살펴본 연구 결과를 바탕으로 치료 원리를 설명합니다.')))
add(2,'msat','동작침','급성 요통이나 관절통으로 걷기 어렵거나 통증이 극심한 환자에게 시행하는 자생의 특수 침치료입니다.',
 sec('치료의 이해',p('환자의 경혈에 침을 놓아 통증을 낮추고 동작을 연결하는 치료입니다. MSAT라는 명칭으로도 소개됩니다.')+sub('요추 동작침',fig('msat-lumbar','요추 동작침에서 침치료와 보행 동작을 연결하는 과정'))+sub('관절 동작침',fig('msat-joint','어깨 관절의 동작을 연결하는 동작침 과정')))+
 sec('급성 요통 임상연구',p('2013년 국제학술지 PAIN에 급성 요통 환자의 동작침 치료 연구가 게재되었습니다. 연구에서는 통증 감소와 기능 회복, 입원 기간 등을 살펴보았습니다.')))
add(2,'medicines','자생 대표 한약 및 보약','척추·관절 치료를 위한 한약과 원기·기력 보강 등을 목적으로 하는 보약을 구분해 이해합니다.',
 sec('척추·관절 치료 한약',cases([('청파전-H','척추관절질환을 위한 자생 고유 처방입니다. 항염증, 뼈 강화, 신경 재생, 연골·척수 신경 보호, 척수 조직 염증 감소, 운동·보행능력 회복을 목적으로 소개됩니다.',''),('청파전-G','혈액순환 개선과 뼈·근육·인대 손상 완화를 위한 처방입니다. 항염증과 뼈·신경·연골·척수 신경 보호, 기력 강화, 근육·인대파열 및 척추디스크·협착증·만성퇴행성 질환 예방을 목적으로 소개됩니다.',''),('청파전-S','진통·소염작용을 통한 근육·신경·관절 통증 완화를 위한 처방입니다. 항염증과 뼈·신경·연골·척수 신경 보호, 근육통·신경통·요통·관절염 완화, 어깨 견관절통·회전근개 파열·급만성 통증 예방을 목적으로 소개됩니다.',''),('신경바로(환)','척추관절 주변 퇴행화된 뼈·신경의 재생을 위한 처방입니다. 염증·부종 완화, 손상 신경 재생, 뼈·연골 강화와 허리·목·퇴행성 디스크 및 척추관절질환 예방을 목적으로 소개됩니다.',''),('청웅바로(환)','염증·부종 제거, 통증 감소와 손상된 뼈·신경·연골 재생, 추간판 탈출증·척추관협착증 등 척추관절질환 예방을 목적으로 소개됩니다.',''),('관절고','연골의 재생·보강과 보호, 관절파괴 억제, 통증 완화 및 퇴행성 관절염 예방을 위한 처방입니다. 손·목·팔목·어깨·무릎 관절염 예방을 목적으로 소개됩니다.','')]))+
 sec('보약',cases([('육공단','허약체질 개선과 기억력 감퇴 예방을 위한 보약입니다. 기억력 증진, 스트레스 개선, 근육강화, 면역력 향상, 원기회복과 만성피로 해소를 목적으로 소개됩니다.',''),('특공단','원기 보강과 스태미나 강화를 위한 보약입니다. 간·뇌세포 보호, 중풍·심장질환 예방, 피로해소, 혈압 강하를 목적으로 소개됩니다.',''),('사향공진단','노년기 혈관질환과 치매 예방을 위한 보약으로 소개됩니다. 심장·신장 기능 강화, 원기회복, 심근경색·뇌경색 예방, 면역력 향상, 만성피로 해소, 독소해독과 스태미나 보강이 설명되어 있습니다.','')])) )
case_data=[('허리디스크 사례 1','case-lumbar1','2021.10.20','2022.12.14','좌측 골반 통증으로 보행 시 다리를 뻗기 어렵고, 심한 요통·종아리 통증으로 자세를 바꾸기 어려웠습니다. 요추 4번과 5번 사이의 디스크 탈출이 관찰되었습니다. 치료 후 탈출 디스크의 용적 감소와 흡수로 신경 압박이 호전되었습니다.'),('허리디스크 사례 2','case-lumbar2','2020.11.02','2022.05.07','수술 권유를 받았으나 비수술 치료를 원해 내원했습니다. 운전 후 발생한 심한 통증과 다리 저림으로 거동이 힘들었으며 요추 4번과 5번 사이의 디스크 탈출이 관찰되었습니다. 치료 후 탈출 디스크의 용적 감소와 흡수로 신경 압박이 해소되었습니다.'),('목디스크 사례 1','case-neck1','2020.08.01','2022.03.15','다른 병원에서 2~3년간 치료했으나 증상이 지속되었습니다. 견갑골·후경부·승모근 통증과 두통이 심했으며 경추 6번과 7번 사이의 디스크 탈출이 관찰되었습니다. 치료 후 탈출 디스크의 용적 감소와 흡수로 신경 압박이 호전되었습니다.'),('목디스크 사례 2','case-neck2','2013.02.12','2021.05.27','학교 식당 근무로 고개를 숙이거나 팔을 많이 사용하던 환자입니다. 2012년 말부터 좌측 팔 통증이 시작되었고, 경추부 통증과 왼쪽 상지 저림·통증이 심해 수술 권유를 받았으나 비수술 치료를 원했습니다. 경추 5번과 6번 사이의 디스크 탈출이 관찰되었으며 치료 후 탈출 디스크의 크기가 줄었습니다.')]
add(2,'treatment-cases','비수술치료 사례','허리디스크와 목디스크 환자의 내원 당시 증상, 치료 전후 MRI와 경과를 함께 살펴봅니다.', ''.join(sec(t,fig(n,f'{t} MRI. 왼쪽 치료 전 {b}, 오른쪽 치료 후 {a}',f'<span>치료 전 · {b}</span><span>치료 후 · {a}</span>')+p(s)) for t,n,b,a,s in case_data))
add(2,'biocenter','자생메디바이오센터','한약과 약침의 처방·조제·품질관리·배송을 연결하는 시설입니다. 표준화된 공정과 단계별 검사가 핵심입니다.',
 sec('한약조제 시스템',p('한의사의 처방에 따라 전문 한약사가 조제합니다. 자동화 시스템으로 시간·압력·온도를 조절하고 외부 오염을 차단한 상태에서 추출합니다.')+timeline([('1 · 실시간 전산 연동','처방에 따라 전문 한약사가 조제'),('2 · 수질 관리','24시간 관리하는 수처리실에서 정수된 물 사용'),('3 · 원료 보관','항온·항습 시스템을 갖춘 약재보관실 이용'),('4 · 자동 탕전','성분 추출과 침전물 감소를 고려한 맞춤 탕전'),('5 · 멸균 처리','가압·가열 멸균'),('6 · 자체 배송','조제에서 배송까지 과정 관리')]))+
 sec('약재부터 한약까지의 안전성 검사',p('잔류 농약·중금속 등 20여 가지 품질관리 검사를 실시하며, 재배환경부터 조제된 한약까지 세 단계로 유해성을 검사합니다.')+ul('<strong>재배환경:</strong> 산지의 생육 상태와 환경 검사','<strong>한약재:</strong> 한국의약품 시험연구원과 그린명품제약에서 유효성·유해성 등 전항목 교차 검사','<strong>한약:</strong> 조제된 한약의 유해성 최종 검사')+fig('quality','실험 장비를 이용해 한약의 안전성을 검사하는 모습'))+
 sec('약재 품질관리',p('국가 위해 요소 기준을 통과한 약재와 식품의약품안전처의 한약재 제조 및 품질관리기준에 따라 인증된 회사의 한약규격품을 사용합니다. 구매 후에도 한약재품질평가위원회가 품질을 관리·감독하며, 항온·항습 환경에서 보관합니다.'))+
 sec('약침 조제와 품질관리',p('KGMP(한국우수의약품제조 및 품질관리기준)에 준하는 시설에서 맞춤 처방에 따라 조제합니다. 세척에서 씰링까지 자동화하고 무균 조제를 시행합니다.')+cases([('무균 시험','모든 약침에 대해 무작위 추출 후 무균 시험을 실시합니다.',''),('엔도톡신 시험','인체에 발열 반응을 일으키는 독성 물질인 엔도톡신을 분석합니다.',''),('불용성 미립자 시험','주사제 기준에 준해 불용성 미립자를 시험합니다.',''),('유기탄소 측정(TOC)','매 조제 시 주사용수의 총 유기탄소를 측정합니다.','')])+p('남양주원외탕전실은 2018년 인증제 도입 이후 최초로 약침 분야 원외탕전실 인증을 통과했습니다.'))+
 more('제이에스뮤지엄에서 만나는 자생의 역사',p('JS MUSEUM은 미디어와 현대 미술 전시로 자생의 역사와 철학을 소개합니다. 긍휼의 유산, 자생 비수술 치료, 자생 아카이브, 자생 오리진, 자생의 숲으로 구성되며 독립운동 정신과 한의학의 발전 과정을 다룹니다.')))
add(2,'academy','자생메디컬아카데미','국내외 의료진에게 자생 비수술 한방통합치료를 소개하고, 교육·연구·국제 교류를 연결하는 국제 교육 전문기관입니다.',
 sec('설립과 교육',p('2019년 자생한방병원 산하 국제 교육 전문기관으로 설립되었습니다. 의사(MD·DO)와 한의사 등 국내외 의료진에게 온·오프라인 교육 콘텐츠를 제공합니다.')+p('국문·영문 동영상, 오디오, 텍스트로 자가학습할 수 있도록 구성하며 미국 CME 보수교육 콘텐츠를 중심으로 교육을 전개해 왔습니다.')+note('교육 이용 안내','현재 교육과정, 연계기관 및 인증 상태는 담당 부서 확인.'))+
 sec('주요 프로그램',cases([('자생국제학술대회(AJA)','통합의학 의료인들이 척추질환 치료·연구와 최신 근거를 교류하고 토론하는 학술대회입니다.',''),('인턴십','예비의대생·의대생에게 한방병원 시스템과 치료 연구를 경험할 기회를 제공합니다.',''),('보수교육 콘텐츠','의료인들과 협업해 CME 콘텐츠를 제작합니다.',''),('실습 프로그램','대학·의료기관과의 교류를 통해 의대생과 의료인에게 자생 치료·한의학 교육을 제공합니다.',''),('국제협력','학술대회와 강연 등으로 한방치료에 대한 이해를 넓힙니다.','')])) )
add(3,'burden','깔딱고개의 법칙','작은 부담도 한 사람에게 쌓이면 버티기 어려워집니다. 동료의 짐을 더하기보다 함께 덜어주는 태도를 생각합니다.',
 sec('이야기의 맥락',p('관악산 정상에서 먹거리를 파는 가족이 무거운 짐을 지고 산을 오릅니다. 가파른 깔딱고개에 이르자 지친 아이들은 음료를 아버지의 지게에 얹고, 아이를 업으려던 어머니도 짐을 더합니다. 이미 힘이 다한 아버지는 불과 몇 개의 물건이 더해진 순간 넘어지고 맙니다.')+p('누군가가 지게의 음료 하나씩만 덜어주었다면 고개를 넘는 데 도움이 되었을 것입니다. 작은 스트레스도 여러 곳에서 쌓이면 누구나 감당하기 어려워진다는 이야기입니다.'))+
 sec('함께 일할 때',ul('자신의 일을 책임지고 작은 이익에 연연해 공동의 목적을 놓치지 않습니다.','조직을 위한 큰 원칙이 정해졌다면 서로 다른 기준으로 흐트러뜨리지 않습니다.','이해관계가 얽힐 때 상대를 배려하고 무거운 짐을 함께 들겠다는 마음을 갖습니다.')))
add(3,'welcome','반색의 마술','환자는 시간을 내고 수고를 들여 병원을 찾습니다. 그 수고를 알아주고 반갑게 맞이하는 데서 응대가 시작됩니다.',
 sec('환자가 오기까지의 시간',p('진료 자체가 한두 시간이어도 준비와 이동, 대기에 드는 시간은 더 깁니다. 비행시간 외에도 공항으로 가고 기다리는 시간이 필요한 것처럼, 환자에게 내원은 하루 일정을 조정해야 하는 일입니다.'))+
 sec('먼저 말을 건네는 환대',p('먼저 반갑게 맞이한 뒤 병의 정황을 묻고 환자의 마음을 살핍니다. 내원과 기다림의 수고를 알아주는 짧은 말부터 생활화합니다.')+'<div class="example">오시느라 수고하셨습니다.<br>날씨가 많이 춥죠?<br>오래 기다리시느라 많이 힘드셨죠?</div>'+p('이러한 환대는 환자가 마음을 열고 의료진의 정성을 느낄 수 있도록 하는 태도입니다.')))
add(3,'touch','터치의 마술','통증뿐 아니라 두려움도 살피는 ‘5초의 배려’. 의료진의 정성 어린 처치와 대화로 환자의 불안을 이해합니다.',
 sec('통증 뒤에 있는 두려움',p('오랜 통증을 겪는 환자는 앞으로도 아픔이 계속되거나 회복하지 못할까 걱정할 수 있습니다. 치료에 시간이 필요하다는 설명을 이해했더라도 당장의 고통은 마음을 흔들 수 있습니다.'))+
 sec('진료 중의 5초의 배려',p('이 이야기는 의료진이 환자를 진료하는 상황을 다룹니다. 설명에만 그치지 않고, 침을 놓기 전에 아픈 부위를 소중하게 살피며 환자와 대화하고 정성스럽게 처치하는 태도를 강조합니다.')+p('굳은 근육을 가볍게 눌러 풀어주는 등 의료진의 짧은 배려를 통해 환자의 두려움을 살피고 치료에 대한 믿음을 돕는다는 의미입니다.')))
add(3,'give','49:51 법칙','도움을 받기 전에 먼저 돕고, 상대에게 조금 더 배려하는 마음이 좋은 인연을 만듭니다.',
 sec('법칙이 시작된 이야기',p('신준식 박사는 병석의 아버지께 무협소설을 읽어드리던 학생에게 고마움을 느꼈습니다. 학생이 진심으로 아버지를 돌볼 수 있도록 자신보다 더 잘 대해 달라고 아내에게 부탁했습니다.'))+
 sec('조금 더 내어주는 마음',p('두 사람이 각각 50만원을 투자해 100만원의 이익을 얻었다고 가정합니다. 자신은 49만원을 갖고 친구에게 51만원을 주는 예로, 받을 몫에서 조금 양보하는 태도를 설명합니다.')+p('상대가 배려를 느끼면 감사와 도움으로 돌아올 수 있다는 것이 이야기의 핵심입니다. 사람과 사람이 서로 도움을 주고받는 관계에서 먼저 내어주는 마음을 강조합니다.')))
add(3,'doing','갈등과 DOING의 법칙','실행할지 망설이는 순간, 시도하지 않고 기회를 놓치는 것은 아닌지 돌아봅니다.',
 sec('망설임에서 실행으로',p('둘 중 하나를 고르기 어렵거나 할지 말지 결정하지 못할 때 갈등이 생깁니다. DOING의 법칙은 꼭 해야 할 일이 있다면 가능성을 찾으며 행동하는 태도를 강조합니다.')+p('비행기 표를 예약하지 못했지만 그날 반드시 출국해야 했던 상황에서, 신준식 박사는 공항에 가서 대기하며 탑승 기회를 찾았다는 경험을 들려줍니다. 포기하고 미루는 것과 일단 시도하는 것의 차이를 설명하는 일화입니다.'))+
 more('공항으로 출발한 또 다른 일화',p('출발이 늦어 제시간에 공항에 도착하기 어려워 보였을 때도, 꼭 가야 하는 상황이라면 일단 출발했다는 이야기가 이어집니다. 도착해 보니 비행기가 연착되어 탑승할 수 있었던 경험을 통해, 시작 전에 가능성을 닫지 않는 태도를 전합니다.')))
add(3,'fingers','세 손가락의 법칙','할 수 없는 이유를 서로 돌리기보다, 해결을 위해 협조하는 태도가 조직의 힘을 키웁니다.',
 sec('세 손가락이 뜻하는 것',p('A를 하려면 B 때문에 안 되고, B를 하려면 C 때문에 안 되며, C를 하려면 다시 A 때문에 안 된다고 말하는 상황을 세 손가락에 비유합니다. 이유만 돌고 해결은 시작되지 않는 상태입니다.'))+
 sec('서로 다른 장점을 함께 쓰기',p('빠르게 행동하는 사람은 기회를 잡지만 수정 비용이 생길 수 있습니다. 신중한 사람은 오류를 줄이지만 때를 놓치거나 동료의 열정을 식게 할 수 있습니다. 관리자는 이 장점들을 연결하고 합의점을 찾는 역할을 합니다.')+ul('타부서의 협조 요청을 자신의 일처럼 적극적으로 돕습니다.','다른 부서의 일에 기여한 성과도 공동의 성과로 봅니다.','관리자는 직원에게 관심과 애정을 갖고 업무의 가치·자부심·비전을 키웁니다.','도울 수 있는데 외면하거나 부주의로 상처를 준 일은 없는지 돌아봅니다.'))+
 more('협조 요청을 거절하던 임원의 이야기',p('한 제조업체의 임원은 동료가 도움을 요청하면 불가능한 이유를 논리적으로 설명했지만, 사장이 지시하면 다음 날 해결책을 가져왔습니다. 이런 일이 반복되자 부서 간 신뢰와 협동심이 약해졌습니다.')+p('이야기는 사장이 모든 일을 대신 해결하기보다 부서들이 스스로 협력할 역량을 키워야 한다고 설명합니다. 공동의 가치관을 나누고 교육하며 분위기를 바꾸자 그 임원도 회사에 기여하는 방향으로 달라졌습니다.')))
add(4,'greeting','인사예절','먼저 본 사람이 먼저, 눈을 맞추며 밝게 인사합니다. 장소와 상황에 맞춰 정성과 존경을 전합니다.',
 sec('기본 수칙',ul('‘내가 먼저’라는 마음으로 인사합니다.','상대와 눈을 맞추고 밝은 표정으로 인사합니다.','인사를 생략하지 않고 상황에 맞게 합니다.'))+
 sec('상황별 인사',cases([('출근·퇴근','밝게 눈을 맞추고, 상대가 먼저 인사하면 반드시 답합니다. 상사보다 먼저 퇴근할 때는 다가가 인사합니다.','안녕하세요. / 좋은 아침입니다.<br>먼저 퇴근하겠습니다. / 내일 뵙겠습니다.'),('조용한 공간·여러 번 마주칠 때','도서관·회의실·화장실 등에서는 목례합니다. 하루에 여러 번 마주칠 때도 목례로 인사합니다.',''),('급한 상황·좁은 공간','급히 지나치거나 엘리베이터 등 좁은 공간에서는 15도 정도의 약례가 적당합니다. 큰 소리의 인사는 자제합니다.',''),('깊은 감사·사죄·중요 고객','두 손을 앞으로 가지런히 모으거나 옆에 두고 45도로 허리를 숙여 정중한 마음을 전합니다.','대단히 감사합니다. / 대단히 죄송합니다. / 처음 뵙겠습니다.')]))+
 note('주의하세요','망설이거나 형식적으로 하는 인사, 말만 하거나 고개만 끄덕이는 인사, 눈을 보지 않는 무표정한 인사를 피합니다. 윗사람보다 높은 위치에서 인사하거나 윗사람에게 “수고하셨습니다”라고 인사하지 않도록 주의합니다.'))
add(4,'conversation','대화예절','분명하고 이해하기 쉽게 말하고, 상대의 이야기가 끝날 때까지 경청합니다. 호칭과 표현도 상황에 맞게 선택합니다.',
 sec('말하기와 듣기',sub('말할 때',ul('용건을 미리 정리하고 주제를 좁혀 구체적으로 말합니다.','밝은 표정으로 눈을 보며, 정확한 발음과 적절한 속도·크기로 말합니다.','불확실한 표현과 흐리는 말끝을 피하고 끝맺음을 분명히 합니다.','감정을 절제하고 상대의 감정이 상하지 않게 순화된 말을 사용합니다.','잘못한 부분은 빠르게 인정하고 솔직하게 사과합니다.'))+sub('들을 때',ul('눈을 맞추고 몸을 살짝 기울이며 호응합니다.','팔짱을 끼거나 다리를 꼬지 않고, 지나치게 의자에 기대지 않습니다.','주위를 두리번거리지 않고 상대에게 집중합니다.','말을 끊지 않으며 질문은 말이 끝난 후에 합니다.'))+note('주의하세요','지나치게 큰 목소리나 빠른 속도, 어려운 전문용어·외국어, 반복되는 화제와 자기 자랑, 정치·종교 관련 대화를 주의합니다.'))+
 sec('대화 중 호칭',cases([('상사','성 또는 이름에 직위와 ‘님’을 붙입니다. 상사보다 더 높은 사람과 대화할 때 본인의 상급자는 ‘이OO팀장’으로 표현합니다.',''),('동료·하급자','성 또는 이름에 직위를 붙입니다. 직급이 없는 동년배 동료나 하급자는 ‘ㅇㅇㅇ선생님’으로 부릅니다. 연장자인 동료에게는 ‘님’을 붙여 존칭을 사용합니다.',''),('직함을 모르는 상사','어떻게 불러야 하는지 먼저 묻습니다. 물어보기 어렵다면 ‘선생님’으로 표현합니다.','제가 어떻게 불러야 할까요?')]))+
 sec('상황별 대화',cases([('상사의 부름을 받았을 때','가능한 즉시 답하고 처음 대면하는 상사에게는 소속과 이름을 밝힙니다.','네, 팀장님 부르셨습니까?<br>안녕하세요. OO팀 OOO입니다. 부르셨습니까?'),('의견·아이디어를 요구받았을 때','결론부터 요점을 간결하고 정확하게 말합니다. 모르는 것은 솔직하게 말합니다.','제 의견은 ~~~합니다.<br>죄송합니다만, 해당 부분은 잘 모르겠습니다. 바로 파악하여 다시 말씀드리겠습니다.'),('상사와 의견이 다를 때','따지듯 말하지 않고 차분하게 상의하며 조율하는 자세를 갖습니다.','팀장님께서 말씀하신 안건에 대하여 이러한 방법으로 추진하면 어떨까 하여 말씀 드립니다만…'),('주의·질책을 받았을 때','감정적인 표정, 변명, 책임 전가를 피합니다. 오해나 부당함이 있다고 판단할 때도 일단 듣고 잠시 후 차근차근 이야기합니다.','죄송합니다. 제가 경솔했던 것 같습니다. 앞으로 주의하도록 하겠습니다.'),('동료가 실수했을 때','큰 소리로 지적하지 않고 조용히 개선 의견을 전달하거나 스스로 인지하도록 돕습니다.',''),('동료와 의견이 대립할 때','자기 의견만 고집하지 않고 타협·조정합니다. 감정 대립이 예상되면 침착함을 유지하고 다시 논의합니다.','일단 이 문제에 대해서는 여기서 대화를 멈추고 서로 더 검토하여 다시 논의해 봅니다.'),('하급자가 일을 잘했을 때','당연하게 여기지 않고 공개적으로 칭찬합니다.','잘했습니다. 고생 많았습니다.<br>OOO선생님 덕분에 좋은 성과를 거두었습니다.'),('하급자가 일을 잘하지 못했을 때','잘못은 분명하게 짚되 분리된 공간에서 개인적으로, 감정을 절제하고 사실 위주로 전달합니다.','')])) )
add(4,'phone','전화예절','벨이 3번 이상 울리기 전에 받고, 소속과 이름을 밝힙니다. 끝인사 후에는 전화를 건 사람이 먼저 끊습니다.',
 sec('기본 수칙',ul('늦게 받았다면 “늦게 받아 죄송합니다”라고 말합니다.','비어 있는 옆자리의 전화가 울리면 빠르게 당겨 받습니다.','전화를 건 사람의 신분과 목적, 통화를 희망하는 상대를 확인합니다.','마무리 인사를 건네고 전화를 건 사람이 먼저 끊도록 합니다.'))+
 sec('이렇게 말합니다',cases([('전화를 받았을 때','소속과 이름을 먼저 밝힙니다.','안녕하십니까? ○○자생 □□팀 ㅇㅇㅇ입니다.'),('전화를 당겨 받았을 때','대신 받았음을 알립니다.','안녕하십니까? 전화 대신 받았습니다.<br>○○자생 □□팀 ㅇㅇㅇ입니다.'),('전화를 걸었을 때','신분과 용건을 밝히고 담당자와 통화할 수 있는지 확인합니다.','안녕하십니까? ○○자생 □□팀 ㅇㅇㅇ입니다.<br>◇◇건으로 연락 드렸는데 담당자와 통화 가능할까요?'),('전화를 끊을 때','끝인사를 전합니다.','감사합니다. / 좋은 하루 보내세요.')]))+
 sec('상황별 전화 응대',cases([('통화 중 상사·고객이 말을 걸 때','통화 상대에게 양해를 구하고 수화기를 막아 짧게 용건을 확인한 뒤 다시 통화합니다.','통화중에 죄송합니다만, 환자분이 문의하셔서요.<br>잠시만 기다려주시겠습니까?'),('부재중인 동료에게 전화가 왔을 때','대신 받아 대화 내용을 메모하고, 끊기 전에 메모한 내용을 반복해 확인합니다.','안녕하십니까? 전화 대신 받았습니다. □□팀 ○○○입니다.<br>담당자가 현재 부재중입니다. 필요하시다면 메모 남겨드리겠습니다.'),('회의 중 전화가 왔을 때','원칙적으로 회의 중에는 받지 않습니다. 공적인 업무로 부득이하게 받아야 한다면 먼저 양해를 구합니다.','(팀장님) 말씀 중에 죄송합니다만, ◇◇건으로 고객이 전화를 걸어온 것 같습니다.<br>잠시 받으러 나갔다 와도 되겠습니까?')]))+
 note('주의하세요','벨을 오래 울리게 두거나 신분을 밝히지 않은 채 통화하지 않습니다. 상대의 신분·목적·희망 통화자를 확인하지 않거나, 끝인사를 생략하거나, 전화를 건 사람보다 먼저 끊지 않도록 주의합니다.'))
add(4,'messenger','메신저 예절과 이용법','인사로 시작하고 마무리하며, 첫 줄에 소속 부서·이름·직책을 밝힙니다. 내용은 간단명료하되 너무 짧게 쓰지 않습니다.',
 sec('메시지 작성 수칙',ul('첫인사와 끝인사를 빠뜨리지 않습니다.','본문 첫 줄에 소속 부서·이름·직책을 밝힙니다.','내용은 간결하고 명확하게 작성합니다.','상태 메시지에 직무와 내선 또는 휴대폰번호를 기재합니다.'))+
 note('주의하세요','급하지 않은 일을 업무시간 외에 보내지 않습니다. 지나친 미사여구, 줄임말·신조어·은어·비속어, 압존법을 피합니다. 대외비 등 민감한 정보는 보내지 않습니다.')+
 sec('소속별 메신저 이용',p('소속에 따라 메신저 그룹이 나뉘어 같은 그룹이 아니면 동일한 메신저를 사용할 수 없는 구조로 안내되어 있습니다. 타 소속 임직원 연락처를 조회하는 시스템으로는 J-TIS(인사정보시스템)가 소개됩니다.')+note('담당 부서 확인','현재 소속별 그룹웨어 주소, 그룹 구분, 메신저 접속 방법과 J-TIS 이용 경로를 확인한 뒤 이용합니다.')))
add(4,'email','이메일 예절과 작성법','제목에서 용건을 알 수 있게 하고, 발신자·수신자·업무 담당자를 명확히 합니다. 발송 전 첨부와 맞춤법을 확인합니다.',
 sec('제목과 본문',ul('발신자는 소속·팀·이름으로 분명히 표시합니다.','제목은 내용을 압축하고, 필요하면 [중요]·[보고서]·[긴급] 등의 표시를 활용합니다.','첫인사 뒤에 글의 목적을 분명히 밝히고 본문을 간단명료하게 씁니다.','중요한 내용은 굵은 글씨나 색상으로 구분합니다.','끝인사와 함께 업무 담당자를 알 수 있는 서명을 기재합니다.'))+
 sec('첨부파일 안내',p('첨부파일이 있다면 본문에도 파일명과 목록을 적습니다. 문서 제목에 필요에 따라 버전명·날짜·작성자를 덧붙여 구분합니다.')+cases([('부서명 + 문서 제목','부서 기준으로 파일을 구분하는 방법입니다.','인사지원팀_6월 교육비'),('작성자 + 문서 제목','작성자 기준으로 파일을 구분하는 방법입니다.','인사지원팀 김자생_6월 교육비'),('문서 종류 + 문서 제목','문서의 성격을 먼저 표시하는 방법입니다.','HRD_6월 교육비')]))+
 sec('발송 전 확인',ul('수신자와 관련 업무 담당자가 정확한가요?','첫인사·끝인사·서명이 있나요?','본문에 첨부파일을 안내했고 실제로 첨부했나요?','맞춤법과 오탈자를 확인했나요?','본문이 불필요하게 길지 않은가요?'))+
 note('주의하세요','본문 없이 첨부파일만 보내지 않습니다. 기본으로 설정된 보안문구는 삭제하지 않습니다.'))
postures=[('걷기','walk','허리를 곧게 펴고 시선은 정면을 향하며 팔을 가볍게 흔듭니다. 뒤꿈치가 먼저 땅에 닿게 하고 발바닥으로 땅을 치듯 전진하는 느낌으로 걷습니다.'),('서 있기·휴대폰 보기','stand','복숭아뼈, 무릎 옆 튀어나온 뼈, 골반, 팔꿈치 뼈, 어깨 뼈와 머리가 일직선이 되도록 합니다. 휴대폰을 볼 때는 고개를 숙이지 말고 손으로 들어 올립니다.'),('무거운 짐 들기','lift','허리를 숙이지 않고 무릎을 굽힙니다. 허리를 세운 상태에서 허벅지 힘을 이용해 들어 올립니다. 부피가 큰 짐은 한 번보다 여러 번 나누어 옮깁니다.'),('앉아서 일하기','sit','상체를 똑바로 세우고 등과 허리를 의자에 밀착합니다. 의자를 책상 가까이 당기고 책상·의자 높이를 조절해 모니터를 눈높이에 최대한 맞춥니다.'),('베개 베기','pillow','목이 자연스러운 C커브를 유지하고 목 근육이 긴장하지 않는 높이를 선택합니다. 너무 낮거나 높은 베개는 목에 무리를 줄 수 있습니다.'),('옆으로 눕기','side-sleep','목뼈와 허리뼈가 최대한 일직선을 유지하도록 합니다. 베개 높이는 10~15cm가 적당하며 무릎 사이에 베개를 끼우면 척추 부담을 줄일 수 있습니다.'),('바로 눕기','back-sleep','천장을 보고 누웠을 때 머리와 목의 높이는 바닥에서 6~8cm 정도로 합니다. 다리를 쭉 폈을 때 통증이나 다리 저림이 있다면 무릎 밑에 베개를 넣는 방법이 있습니다.')]
