 if marker is None:raise ValueError((slug,heading))
 start=body.index(marker)+len(marker)
 if marker.startswith('<summary>'):
  end=body.index('</div></details>',start)
 elif marker.startswith('<h3>'):
  end=body.index('</section>',start)
 else:
  # h2 sections may contain nested situation sections.
  depth=1;end=None
  for match in re.finditer(r'<section\b[^>]*>|</section>',body[start:]):
   depth+= -1 if match[0]=='</section>' else 1
   if depth==0:end=start+match.start();break
